UALSAEQARuntimeVisualComponent::UALSAEQARuntimeVisualComponent(){PrimaryComponentTick.bCanEverTick=true;}
void UALSAEQARuntimeVisualComponent::BeginPlay(){Super::BeginPlay();if(bBuildOnBeginPlay)RebuildVisual();}
void UALSAEQARuntimeVisualComponent::ClearVisual(){if(IsValid(ImportedMeshComponent)){ImportedMeshComponent->DestroyComponent();ImportedMeshComponent=nullptr;}for(USceneComponent*P:VisualParts)if(IsValid(P))P->DestroyComponent();VisualParts.Reset();AnimatedParts.Reset();bUsingImportedArt=false;}
bool UALSAEQARuntimeVisualComponent::TryBuildImportedArt(){
 AActor*O=GetOwner(); if(!O||!O->GetRootComponent()) return false;
 USkeletalMesh*Mesh=nullptr; TSubclassOf<UAnimInstance> AnimClass=ImportedAnimClass; FVector Loc=ImportedRelativeLocation; FRotator Rot=ImportedRelativeRotation; FVector Scale=ImportedRelativeScale; TArray<TSoftObjectPtr<UMaterialInterface>> Materials;
 if(!ArtProfile.IsNull()){
  UALSAEQAArtProfile*Profile=ArtProfile.LoadSynchronous();
  if(Profile){Mesh=Profile->Mesh.LoadSynchronous(); if(Profile->AnimClass)AnimClass=Profile->AnimClass; Loc=Profile->RelativeLocation; Rot=Profile->RelativeRotation; Scale=Profile->RelativeScale; Materials=Profile->MaterialOverrides;}
 }
 if(!Mesh&&!ImportedSkeletalMesh.IsNull()) Mesh=ImportedSkeletalMesh.LoadSynchronous();
 if(!Mesh) return false;
 USkeletalMeshComponent*C=NewObject<USkeletalMeshComponent>(O); if(!C) return false;
 C->SetSkeletalMesh(Mesh); C->SetCollisionEnabled(ECollisionEnabled::NoCollision); C->SetMobility(EComponentMobility::Movable);
 C->AttachToComponent(O->GetRootComponent(),FAttachmentTransformRules::KeepRelativeTransform); C->SetRelativeLocation(Loc); C->SetRelativeRotation(Rot); C->SetRelativeScale3D(Scale);
 if(AnimClass) C->SetAnimInstanceClass(AnimClass);
 C->RegisterComponent();
 for(int32 Index=0;Index<Materials.Num()&&Index<C->GetNumMaterials();++Index){if(UMaterialInterface*M=Materials[Index].LoadSynchronous())C->SetMaterial(Index,M);}
 ImportedMeshComponent=C; bUsingImportedArt=true; VisualParts.Add(C); return true;
}
bool UALSAEQARuntimeVisualComponent::PlayProfileMontage(TSoftObjectPtr<UAnimMontage> MontageAsset){
 if(!bUsingImportedArt||!IsValid(ImportedMeshComponent)||MontageAsset.IsNull())return false;
 UAnimMontage*Montage=MontageAsset.LoadSynchronous(); if(!Montage)return false;
 UAnimInstance*Anim=ImportedMeshComponent->GetAnimInstance(); if(!Anim)return false;
 return Anim->Montage_Play(Montage)>0.f;
}
bool UALSAEQARuntimeVisualComponent::PlayLightAttackAnimation(){UALSAEQAArtProfile*P=ArtProfile.IsNull()?nullptr:ArtProfile.LoadSynchronous();return P&&PlayProfileMontage(P->LightAttack);}
bool UALSAEQARuntimeVisualComponent::PlayHeavyAttackAnimation(){UALSAEQAArtProfile*P=ArtProfile.IsNull()?nullptr:ArtProfile.LoadSynchronous();return P&&PlayProfileMontage(P->HeavyAttack);}
bool UALSAEQARuntimeVisualComponent::PlayHitReactionAnimation(){UALSAEQAArtProfile*P=ArtProfile.IsNull()?nullptr:ArtProfile.LoadSynchronous();return P&&PlayProfileMontage(P->HitReact);}
bool UALSAEQARuntimeVisualComponent::PlayDeathAnimation(){UALSAEQAArtProfile*P=ArtProfile.IsNull()?nullptr:ArtProfile.LoadSynchronous();return P&&PlayProfileMontage(P->Death);}
bool UALSAEQARuntimeVisualComponent::PlaySpecialAbilityAnimation(){UALSAEQAArtProfile*P=ArtProfile.IsNull()?nullptr:ArtProfile.LoadSynchronous();return P&&PlayProfileMontage(P->SpecialAbility);}
void UALSAEQARuntimeVisualComponent::AddMeshPart(const TArray<FVector>&V,const TArray<int32>&T,const FVector&Loc,const FRotator&Rot,const FVector&Scale,const FLinearColor&Color,bool Animate){AActor*O=GetOwner();if(!O||!O->GetRootComponent())return;UProceduralMeshComponent*C=NewObject<UProceduralMeshComponent>(O);if(!C)return;TArray<FVector>N;N.Init(FVector::UpVector,V.Num());TArray<FVector2D>UV;UV.Init(FVector2D::ZeroVector,V.Num());TArray<FColor>Col;Col.Init(Color.ToFColor(true),V.Num());C->CreateMeshSection(0,V,T,N,UV,Col,TArray<FProcMeshTangent>(),true);C->SetCollisionEnabled(ECollisionEnabled::NoCollision);C->SetMobility(EComponentMobility::Movable);C->AttachToComponent(O->GetRootComponent(),FAttachmentTransformRules::KeepRelativeTransform);C->SetRelativeLocation(Loc);C->SetRelativeRotation(Rot);C->SetRelativeScale3D(Scale);C->RegisterComponent();VisualParts.Add(C);if(Animate)AnimatedParts.Add(C);}
void UALSAEQARuntimeVisualComponent::AddEllipsoid(const FVector&L,const FVector&S,const FLinearColor&C,bool A,int32 Seg,int32 Rings){TArray<FVector>V;TArray<int32>T;for(int r=0;r<=Rings;r++){float p=-PI*.5f+PI*r/Rings,cp=FMath::Cos(p),z=FMath::Sin(p);for(int s=0;s<Seg;s++){float q=2*PI*s/Seg;V.Add(FVector(S.X*cp*FMath::Cos(q),S.Y*cp*FMath::Sin(q),S.Z*z));}}for(int r=0;r<Rings;r++)for(int s=0;s<Seg;s++){int a=r*Seg+s,b=r*Seg+(s+1)%Seg,c=(r+1)*Seg+(s+1)%Seg,d=(r+1)*Seg+s;T.Append({a,b,c,a,c,d});}AddMeshPart(V,T,L,FRotator::ZeroRotator,FVector::OneVector,C,A);}
void UALSAEQARuntimeVisualComponent::AddTube(const FVector&L,float R0,float R1,float H,const FVector&S,const FLinearColor&C,const FRotator&R,bool A,int32 Seg){TArray<FVector>V;TArray<int32>T;for(int z=0;z<2;z++)for(int s=0;s<Seg;s++){float q=2*PI*s/Seg,rr=z?R1:R0;V.Add(FVector(rr*FMath::Cos(q),rr*FMath::Sin(q),z?H:0));}for(int s=0;s<Seg;s++){int a=s,b=(s+1)%Seg,c=Seg+(s+1)%Seg,d=Seg+s;T.Append({a,b,c,a,c,d});}AddMeshPart(V,T,L,R,S,C,A);}
void UALSAEQARuntimeVisualComponent::AddWeaponVisual(){if(VisualRole==EALSAEQAVisualRole::Hero||VisualRole==EALSAEQAVisualRole::Companion){AddTube(FVector(48,0,35),3,1.2,78,FVector(1,1,1),FLinearColor(.55,.58,.62),FRotator(0,0,-8),true);AddEllipsoid(FVector(48,0,32),FVector(7,3,4),FLinearColor(.18,.10,.05));}}
void UALSAEQARuntimeVisualComponent::AddStormVisual(){if(!bAddStormLight||(VisualRole!=EALSAEQAVisualRole::Hero&&VisualRole!=EALSAEQAVisualRole::Boss))return;AActor*O=GetOwner();if(!O||!O->GetRootComponent())return;UPointLightComponent*L=NewObject<UPointLightComponent>(O);L->SetMobility(EComponentMobility::Movable);L->SetIntensity(850);L->SetAttenuationRadius(380);L->SetLightColor(FLinearColor(.22,.52,1));L->AttachToComponent(O->GetRootComponent(),FAttachmentTransformRules::KeepRelativeTransform);L->SetRelativeLocation(FVector(0,0,150));L->RegisterComponent();VisualParts.Add(L);}
void UALSAEQARuntimeVisualComponent::RebuildVisual(){ClearVisual();if(TryBuildImportedArt()){return;}switch(VisualRole){case EALSAEQAVisualRole::Hero:AddEllipsoid(FVector(0,0,64),FVector(34,23,52),FLinearColor(.18,.28,.38),true);AddEllipsoid(FVector(0,0,132),FVector(24,22,27),FLinearColor(.58,.36,.22));AddTube(FVector(-14,-7,6),11,8,45,FVector(1,1,1),FLinearColor(.12,.14,.17),FRotator::ZeroRotator,true);AddTube(FVector(14,-7,6),11,8,45,FVector(1,1,1),FLinearColor(.12,.14,.17),FRotator::ZeroRotator,true);AddEllipsoid(FVector(-14,-9,6),FVector(14,12,8),FLinearColor(.08,.07,.06));AddEllipsoid(FVector(14,-9,6),FVector(14,12,8),FLinearColor(.08,.07,.06));AddEllipsoid(FVector(-34,0,100),FVector(17,14,11),FLinearColor(.16,.22,.30));AddEllipsoid(FVector(34,0,100),FVector(17,14,11),FLinearColor(.16,.22,.30));AddTube(FVector(-38,0,54),9,7,44,FVector(1,1,1),FLinearColor(.22,.30,.38),FRotator::ZeroRotator,true);AddTube(FVector(38,0,54),9,7,44,FVector(1,1,1),FLinearColor(.22,.30,.38),FRotator::ZeroRotator,true);AddEllipsoid(FVector(0,0,154),FVector(26,23,12),FLinearColor(.05,.035,.025));break;case EALSAEQAVisualRole::Companion:AddEllipsoid(FVector(0,0,62),FVector(30,22,48),FLinearColor(.16,.24,.40),true);AddEllipsoid(FVector(0,0,130),FVector(23,21,27),FLinearColor(.62,.40,.27));AddEllipsoid(FVector(0,-5,65),FVector(36,27,47),FLinearColor(.10,.16,.30));AddTube(FVector(-35,0,54),8,6,44,FVector(1,1,1),FLinearColor(.30,.22,.16),FRotator::ZeroRotator,true);AddTube(FVector(35,0,54),8,6,44,FVector(1,1,1),FLinearColor(.30,.22,.16),FRotator::ZeroRotator,true);AddEllipsoid(FVector(0,0,149),FVector(26,23,14),FLinearColor(.06,.025,.02));break;case EALSAEQAVisualRole::Enemy:AddEllipsoid(FVector(0,0,74),FVector(38,27,60),FLinearColor(.24,.18,.16),true);AddEllipsoid(FVector(0,0,150),FVector(28,25,30),FLinearColor(.20,.12,.08));AddTube(FVector(-19,-7,6),13,9,50,FVector(1,1,1),FLinearColor(.14,.13,.13),FRotator::ZeroRotator,true);AddTube(FVector(19,-7,6),13,9,50,FVector(1,1,1),FLinearColor(.14,.13,.13),FRotator::ZeroRotator,true);AddEllipsoid(FVector(-42,0,108),FVector(21,17,13),FLinearColor(.30,.22,.16));AddEllipsoid(FVector(42,0,108),FVector(21,17,13),FLinearColor(.30,.22,.16));AddTube(FVector(-46,0,55),11,8,52,FVector(1,1,1),FLinearColor(.22,.17,.14),FRotator::ZeroRotator,true);AddTube(FVector(46,0,55),11,8,52,FVector(1,1,1),FLinearColor(.22,.17,.14),FRotator::ZeroRotator,true);break;case EALSAEQAVisualRole::Boss:AddEllipsoid(FVector(0,0,105),FVector(58,40,85),FLinearColor(.12,.13,.18),true,16,9);AddEllipsoid(FVector(0,0,205),FVector(39,35,39),FLinearColor(.18,.12,.10));AddTube(FVector(-34,-8,8),19,13,72,FVector(1,1,1),FLinearColor(.10,.10,.14),FRotator::ZeroRotator,true);AddTube(FVector(34,-8,8),19,13,72,FVector(1,1,1),FLinearColor(.10,.10,.14),FRotator::ZeroRotator,true);break;case EALSAEQAVisualRole::Snake:for(int i=0;i<12;i++)AddEllipsoid(FVector(i*30,18*FMath::Sin(i*.7f),30+8*FMath::Sin(i*.5f)),FVector(23,18,19),FLinearColor(.12,.30,.13),false,12,6);AddEllipsoid(FVector(365,0,78),FVector(30,24,27),FLinearColor(.16,.34,.15));break;case EALSAEQAVisualRole::Mount:AddEllipsoid(FVector(0,0,70),FVector(45,25,35),FLinearColor(.30,.16,.08),true);AddEllipsoid(FVector(55,0,92),FVector(25,20,22),FLinearColor(.34,.19,.10));for(float x=-35;x<=35;x+=23)AddTube(FVector(x,0,25),8,6,40,FVector(1,1,1),FLinearColor(.20,.11,.06),FRotator::ZeroRotator,true);break;case EALSAEQAVisualRole::Weapon:AddTube(FVector(0,0,0),4,1,110,FVector(1,1,1),FLinearColor(.55,.58,.62));break;}if(bAddWeapon)AddWeaponVisual();AddStormVisual();}
void UALSAEQARuntimeVisualComponent::SetVisualRole(EALSAEQAVisualRole N){VisualRole=N;if(IsRegistered())RebuildVisual();}
void UALSAEQARuntimeVisualComponent::TickComponent(float D,ELevelTick T,FLevelTickFunction*F){Super::TickComponent(D,T,F);if(bUsingImportedArt)return;AnimTime+=D;ACharacter*Ch=Cast<ACharacter>(GetOwner());float Speed=Ch?Ch->GetVelocity().Size2D():0;float Rate=FMath::Clamp(Speed/350.f,0.f,1.f);for(int32 i=0;i<AnimatedParts.Num();++i){if(!IsValid(AnimatedParts[i]))continue;float P=AnimTime*(3.0f+Rate*7.0f)+i*.8f;AnimatedParts[i]->SetRelativeRotation(FRotator(FMath::Sin(P)*2.f,FMath::Sin(P*.7f)*1.5f,FMath::Sin(P)*5.f*Rate));}}
